struct TrieNode {
    TrieNode* children[2] = {nullptr, nullptr};
    int count = 0;
};

class Solution {
    int countLessEqual(const vector<int>& nums, int k) {
        TrieNode* root = new TrieNode();
        int total = 0;
        for (int num : nums) {
            TrieNode* node = root;
            int ans = 0;
            for (int bit = 15; bit >= 0; --bit) {
                if (!node) break;
                int b = (num >> bit) & 1;
                int kb = (k >> bit) & 1;
                if (kb == 1) {
                    if (node->children[b]) ans += node->children[b]->count;
                    node = node->children[1 - b];
                } else {
                    node = node->children[b];
                }
            }
            if (node) ans += node->count;
            total += ans;

            TrieNode* curr = root;
            for (int bit = 15; bit >= 0; --bit) {
                int b = (num >> bit) & 1;
                if (!curr->children[b]) curr->children[b] = new TrieNode();
                curr = curr->children[b];
                curr->count++;
            }
        }
        return total;
    }
public:
    int countPairs(vector<int>& nums, int low, int high) {
        return countLessEqual(nums, high) - countLessEqual(nums, low - 1);
    }
};

class Solution {
    static class TrieNode {
        TrieNode[] children = new TrieNode[2];
        int count = 0;
    }

    private int countLessEqual(int[] nums, int k) {
        TrieNode root = new TrieNode();
        int total = 0;
        for (int num : nums) {
            TrieNode node = root;
            int ans = 0;
            for (int bit = 15; bit >= 0; --bit) {
                if (node == null) break;
                int b = (num >> bit) & 1;
                int kb = (k >> bit) & 1;
                if (kb == 1) {
                    if (node.children[b] != null) ans += node.children[b].count;
                    node = node.children[1 - b];
                } else {
                    node = node.children[b];
                }
            }
            if (node != null) ans += node.count;
            total += ans;

            TrieNode curr = root;
            for (int bit = 15; bit >= 0; --bit) {
                int b = (num >> bit) & 1;
                if (curr.children[b] == null) curr.children[b] = new TrieNode();
                curr = curr.children[b];
                curr.count++;
            }
        }
        return total;
    }

    public int countPairs(int[] nums, int low, int high) {
        return countLessEqual(nums, high) - countLessEqual(nums, low - 1);
    }
}

