var countPairs = function(nums, low, high) {
    function countLessEqual(k) {
        const root = { children: [null, null], count: 0 };
        let total = 0;
        for (const num of nums) {
            let node = root;
            let ans = 0;
            for (let bit = 15; bit >= 0; --bit) {
                if (!node) break;
                const b = (num >> bit) & 1;
                const kb = (k >> bit) & 1;
                if (kb === 1) {
                    if (node.children[b]) ans += node.children[b].count;
                    node = node.children[1 - b];
                } else {
                    node = node.children[b];
                }
            }
            if (node) ans += node.count;
            total += ans;

            let curr = root;
            for (let bit = 15; bit >= 0; --bit) {
                const b = (num >> bit) & 1;
                if (!curr.children[b]) {
                    curr.children[b] = { children: [null, null], count: 0 };
                }
                curr = curr.children[b];
                curr.count++;
            }
        }
        return total;
    }

    return countLessEqual(high) - countLessEqual(low - 1);
